window.kbPageData["views/entry/k-92239a56f08a0043"] = {"key":"entry/k-92239a56f08a0043","state":{"route":"entry/k-92239a56f08a0043"},"node":{"id":"k-92239a56f08a0043","mode":"k","title":"对“义乌发展经验”作出重要指示（4 月 23 日）","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["governance","industry","market"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["重要会议讲话"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"对“义乌发展经验”作出重要指示（4 月 23 日）","slug":"06f773ef1b30"}],"directorySummary":"考点十六 对“义乌发展经验”作出重要指示（4 月 23 日）\n重要指示指出，义乌小商品闯出大市场、做成大产业，形成“义乌发展经验”，这是因地制宜\n发展县域经济的成功实践；要结合开展树立和践行正确政绩观学习教育，把“义乌发展经验”\n进一步总结好、运用好，引导各地区立足自身资源禀赋，尊重基层和群众首创精…","sources":[{"id":"ab1f1f1f5f09c4a3","label":"对“义乌发展经验”作出重要指示（4 月 23 日）","topic":"重要会议讲话","category":"时政","text":"考点十六 对“义乌发展经验”作出重要指示（4 月 23 日）\n重要指示指出，义乌小商品闯出大市场、做成大产业，形成“义乌发展经验”，这是因地制宜\n发展县域经济的成功实践；要结合开展树立和践行正确政绩观学习教育，把“义乌发展经验”\n进一步总结好、运用好，引导各地区立足自身资源禀赋，尊重基层和群众首创精神，探索走出\n符合各自实际的高质量发展之路。2006 年 6 月曾以“六大内涵、十二个字、五个结合”加以\n概括，“十二个字”即“莫名其妙、无中生有、点石成金”的发展；改革创新是“义乌发展经\n验”最鲜明的特质。","source":{"doc":"4e539a366dce19555ccf","first":4,"last":4,"page":4,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"industry","title":"产业升级与新质生产力"},{"slug":"market","title":"统一大市场与公平竞争"},{"slug":"governance","title":"基层治理与群众参与"}],"units":{"k-92239a56f08a0043":[]}};
